"use strict";
// Floor 9: no plaintext credentials or issuer private keys in the tree.
//
// Scans what git tracks (git ls-files), not the working directory: a generated issuer key or a
// wallet on a developer's disk is fine as long as it is ignored. TEST-ONLY vectors (keys and
// secrets that are sha256 of public labels, generated by circuits/scripts/gen-vectors.js) are
// allowed only when the file says so at top level.
const { describe, test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("fs");
const path = require("path");
const h = require("./helpers");

const tracked = () => h.git("ls-files", "-z").split("\0").filter(Boolean);
const isIgnored = (p) => {
  try {
    h.git("check-ignore", "-q", "--no-index", p);
    return true;
  } catch (_) {
    return false;
  }
};
const BINARY = /\.(wasm|zkey|ptau|png|jpg|gif|ico|pdf|r1cs|wtns)$/;

// G2-S1-SAFETY-022: the conditional status rule (F9.12). A key is "multi-party" only with the full
// evidence; anything less must say DEV-ONLY and name the single-party limitation.
const SETUP_NAMES = ["integrated_access_v3", "integrated_access_v4"];
const PUBLIC_PHASE1 = new Set(["pse-ppot-0080", "hermez"]);
const HEX128 = /^[0-9a-f]{128}$/;
const committedManifest = (name) => h.readJson(h.r("circuits", "setup", `${name}.manifest.json`));
const claimsMultiParty = (m) => Boolean(m.phase2) && typeof m.phase2.contributions === "number" && m.phase2.contributions >= 2;
const F906_SUPERSEDED = SETUP_NAMES.some((n) => claimsMultiParty(committedManifest(n)))
  ? "superseded by F9.12 (G2-S1-SAFETY-022), itself superseded by F9.13: a multi-party phase 2 is committed"
  : false;

/**
 * Every way manifest `m` presents its key as more trustworthy than its provenance supports.
 * `readTranscript(rel)` returns the text of the transcript the manifest names, or null.
 * Returns [] for a consistent manifest.
 */
function provenanceViolations(m, readTranscript) {
  const v = [];
  const lim = Array.isArray(m.limitations) ? m.limitations.filter((l) => typeof l === "string") : [];
  const has = (re) => lim.some((l) => re.test(l));
  const p2 = m.phase2 && typeof m.phase2 === "object" ? m.phase2 : {};
  const n = p2.contributions;
  if (!["DEV-ONLY", "DEMO-ONLY"].includes(m.status)) v.push(`status ${JSON.stringify(m.status)} is neither DEV-ONLY nor DEMO-ONLY`);
  if (typeof m.status_detail !== "string" || !/not for production/.test(m.status_detail)) v.push("status_detail does not say \"not for production\"");
  if (typeof n !== "number" || !Number.isInteger(n) || n < 1) {
    v.push(`phase2.contributions ${JSON.stringify(n)} is not a positive integer`);
    return v;
  }
  const publicPhase1 = Boolean(m.ptau) && PUBLIC_PHASE1.has(m.ptau.source);
  const publicBeacon = p2.beacon_public === true;

  // multi-party evidence: >= 2 contributions, public phase 1, public beacon, transcript hash, contributors
  const why = [];
  if (n < 2) why.push("fewer than 2 contributions");
  if (!publicPhase1) why.push("phase 1 is not a public ceremony");
  if (!publicBeacon) why.push("beacon is not public");
  if (n >= 2) {
    if (typeof p2.beacon_hash !== "string" || !/^(0x)?[0-9a-fA-F]{16,}$/.test(p2.beacon_hash)) why.push("no beacon_hash");
    if (typeof p2.beacon_contribution_hash !== "string" || !HEX128.test(p2.beacon_contribution_hash)) why.push("no beacon_contribution_hash");
    if (typeof p2.transcript_sha256 !== "string" || !/^[0-9a-f]{64}$/.test(p2.transcript_sha256)) why.push("no transcript_sha256");
    if (typeof p2.transcript !== "string" || p2.transcript === "") why.push("no transcript path");
    const cs = p2.contributors;
    if (!Array.isArray(cs) || cs.length !== n) why.push(`contributors do not list ${n} entries`);
    else {
      cs.forEach((c, i) => {
        if (!c || c.order !== i + 1 || typeof c.participant !== "string" || c.participant.trim() === "" || typeof c.hash !== "string" || !HEX128.test(c.hash)) {
          why.push(`contributor #${i + 1} is incomplete`);
        }
      });
      if (new Set(cs.map((c) => c && c.hash)).size !== cs.length) why.push("contributor hashes repeat");
    }
    // the transcript the manifest names must be the one it hashed, and say the same thing
    if (why.length === 0) {
      const text = readTranscript(p2.transcript);
      if (typeof text !== "string") why.push(`transcript ${p2.transcript} is not available`);
      else {
        const crypto = require("crypto");
        if (crypto.createHash("sha256").update(text).digest("hex") !== p2.transcript_sha256) why.push("transcript_sha256 does not match the transcript");
        let t = null;
        try {
          t = JSON.parse(text);
        } catch (_) {
          why.push("transcript is not JSON");
        }
        if (t) {
          const tc = (t.contributions || []).map((c) => ({ order: c.order, participant: c.participant, hash: c.contribution_hash }));
          if (JSON.stringify(tc) !== JSON.stringify(cs)) why.push("contributors differ from the transcript");
          if (!t.beacon || t.beacon.public !== true || t.beacon.hash !== p2.beacon_hash || t.beacon.contribution_hash !== p2.beacon_contribution_hash) {
            why.push("beacon differs from the transcript");
          }
          if (!t.ptau || !m.ptau || t.ptau.blake2b !== m.ptau.blake2b) why.push("phase 1 differs from the transcript");
        }
      }
    }
  }
  const multi = why.length === 0;

  if (multi) {
    if (m.status !== "DEMO-ONLY") v.push(`multi-party evidence complete but status is ${m.status}, not DEMO-ONLY`);
    if (!has(new RegExp(`multi-party phase 2 \\(${n} contributors.*could forge proofs`))) v.push("no multi-party limitation naming the contributor count and the collusion risk");
    if (has(/single-party phase 2/)) v.push("a multi-party key still carries the single-party limitation");
    if (!/multi-party/.test(m.status_detail || "")) v.push("status_detail does not say multi-party");
  } else {
    if (m.status !== "DEV-ONLY") v.push(`status ${m.status} without multi-party evidence (${why.join("; ")})`);
    if (n < 2) {
      if (!has(/single-party phase 2.*could forge proofs/)) v.push("single-party key without the single-party limitation");
      if (has(/multi-party phase 2 \(/)) v.push("single-party key claims a multi-party limitation");
      if (!/single-party phase 2/.test(m.status_detail || "")) v.push("status_detail of a single-party key does not say so");
    } else {
      if (!publicBeacon && !has(/beacon is local randomness/)) v.push("non-public beacon not listed as a limitation");
      if (!/single-party phase 2|local or unknown phase 1|beacon not public/.test(m.status_detail || "")) v.push("DEV-ONLY status_detail does not say why");
    }
  }
  return v;
}

/** The fixtures' TEST_ONLY text against the v4 manifest it is proved under. */
function fixtureTextViolations(text, m) {
  const v = [];
  if (typeof text !== "string" || !/TEST-ONLY/.test(text)) return ["TEST_ONLY marker missing"];
  if (!/Never use outside tests|not for production/.test(text)) v.push("TEST_ONLY does not restrict use to tests");
  const n = m.phase2 && m.phase2.contributions;
  if (m.status === "DEMO-ONLY") {
    if (!/DEMO-ONLY/.test(text)) v.push("TEST_ONLY does not name DEMO-ONLY");
    if (!/multi-party/.test(text)) v.push("TEST_ONLY does not say multi-party");
    if (/single-party/.test(text)) v.push("TEST_ONLY still says single-party under a multi-party key");
  } else {
    if (!/DEV-ONLY/.test(text)) v.push(`TEST_ONLY does not name DEV-ONLY (manifest status ${m.status})`);
    if (!(typeof n === "number" && n >= 2)) {
      if (!/single-party phase 2.*could forge proofs/.test(text)) v.push("TEST_ONLY of a single-party key does not name the single-party limitation");
      if (/multi-party phase 2/.test(text)) v.push("TEST_ONLY claims multi-party for a single-party key");
    }
  }
  return v;
}

/**
 * F9.13 tightening: a manifest carries EXACTLY ONE phase-2 limitation line, and it agrees with
 * `phase2.contributions` / `phase2.contributors` (and with `phase2.limitation` when present).
 * A multi-party key with an extra contradictory "multi-party phase 2 (1 contributors: x)" line, or a
 * line naming another count or other people, is refused. Returns [] when consistent.
 */
function phase2LineViolations(m) {
  const v = [];
  const lim = Array.isArray(m.limitations) ? m.limitations.filter((l) => typeof l === "string") : [];
  const p2 = m.phase2 && typeof m.phase2 === "object" ? m.phase2 : {};
  const n = p2.contributions;
  const lines = lim.filter((l) => /(single|multi)-party phase 2/.test(l));
  if (lines.length !== 1) v.push(`${lines.length} phase-2 limitation lines (exactly one required)`);
  if (typeof n !== "number" || !Number.isInteger(n) || n < 1) return v; // provenanceViolations reports it
  const cs = Array.isArray(p2.contributors) ? p2.contributors : null;
  for (const l of lines) {
    if (/single-party phase 2/.test(l) && /multi-party phase 2/.test(l)) v.push("one phase-2 line says both single- and multi-party");
    if (/multi-party phase 2/.test(l)) {
      const mm = /multi-party phase 2 \((\d+) contributors?(?::\s*([^)]*))?\)/.exec(l);
      if (!mm) {
        v.push("multi-party line without a contributor count");
        continue;
      }
      const k = Number(mm[1]);
      if (n < 2) v.push(`multi-party line on a key with ${n} contribution(s)`);
      if (k !== n) v.push(`multi-party line names ${k} contributors, phase2.contributions is ${n}`);
      if (!cs || cs.length !== k) v.push(`multi-party line names ${k} contributors, phase2.contributors lists ${cs ? cs.length : "none"}`);
      else if (mm[2] !== undefined && mm[2] !== cs.map((c) => c && c.participant).join(", ")) v.push("multi-party line names other contributors than phase2.contributors");
    } else if (n >= 2) {
      v.push(`single-party line on a key with ${n} contributions`);
    }
  }
  if (p2.limitation !== undefined && (lines.length !== 1 || p2.limitation !== lines[0])) v.push("phase2.limitation differs from the phase-2 limitation line");
  return v;
}
/** F9.13: provenanceViolations plus the one-consistent-phase-2-line rule. */
const strictViolations = (m, read) => [...provenanceViolations(m, read), ...phase2LineViolations(m)];

const readTreeFile = (rel) => {
  if (typeof rel !== "string" || rel.startsWith("..") || path.isAbsolute(rel)) return null;
  const abs = h.r(...rel.split("/"));
  return fs.existsSync(abs) ? fs.readFileSync(abs, "utf8") : null;
};

describe("floor 9: no plaintext credentials or issuer private keys in the tree", () => {
  test("F9.01 no tracked file under the issuer key directory, no key/env/wallet file names", () => {
    const bad = tracked().filter((f) =>
      /^issuer\/keys\//.test(f) ||
      /(^|\/)\.zkgate\//.test(f) ||
      /\.credential\.json$/.test(f) ||
      /(^|\/)\.env(\.|$)/.test(f) ||
      /\.(pem|key|p12|pfx|jks)$/.test(f) ||
      /(^|\/)(id_rsa|id_ed25519|issuer\.key|registry\.json)$/.test(f) ||
      /(^|\/)issuer\/data\//.test(f));
    assert.deepEqual(bad, []);
  });

  test("F9.02 no tracked text file contains PEM private-key material or is a bare 32-byte hex key", () => {
    let scanned = 0;
    for (const f of tracked()) {
      if (BINARY.test(f) || f.startsWith("tests/safety/")) continue;
      const abs = path.join(h.REPO, f);
      if (!fs.existsSync(abs) || fs.statSync(abs).size > 5 * 1024 * 1024) continue;
      const text = fs.readFileSync(abs, "utf8");
      scanned += 1;
      assert.ok(!/-----BEGIN [A-Z ]*PRIVATE KEY-----/.test(text), `${f} holds a PEM private key`);
      assert.ok(!/^\s*[0-9a-fA-F]{64}\s*$/.test(text), `${f} looks like a raw issuer key (64 hex chars)`);
      assert.ok(!/"privateKey"\s*:\s*"[0-9a-fA-Fx]{40,}"/.test(text) || /TEST[-_]ONLY/.test(text), `${f} carries a privateKey field without a TEST-ONLY marker`);
    }
    assert.ok(scanned > 100, `only ${scanned} files scanned`);
  });

  test("F9.03 no tracked JSON is a wallet credential; any JSON holding credentialSecret is TEST-ONLY at top level", () => {
    for (const f of tracked().filter((x) => x.endsWith(".json"))) {
      const text = fs.readFileSync(path.join(h.REPO, f), "utf8");
      assert.ok(!text.includes("\"zk-access-gate/credential\""), `${f} is a wallet credential file`);
      if (/"credentialSecret"\s*:\s*"\d/.test(text)) {
        const o = JSON.parse(text);
        assert.ok(typeof o.TEST_ONLY === "string" && /TEST-ONLY/.test(o.TEST_ONLY), `${f} holds a credentialSecret without a top-level TEST_ONLY marker`);
      }
    }
  });

  test("F9.04 the secrets locations are ignored by git", () => {
    for (const p of ["issuer/keys/issuer.key", "issuer/keys/.issuer.key.1.tmp", ".zkgate/credentials/alice.json", "client/.zkgate/pins.json",
      "alice.credential.json", "issuer/data/registry.json", ".env", "tests/credential_v2_private.json"]) {
      assert.ok(isIgnored(p), `${p} is not ignored`);
    }
    // tests/safety/** itself must NOT be ignored (append-only suite, floor 10)
    assert.ok(!isIgnored("tests/safety/MANIFEST.json"));
    assert.ok(!isIgnored("tests/safety/package.json"));
  });

  test("F9.05 the issuer generates its key once, 0600 in a 0700 dir, refuses a readable key, and never uses the TEST-ONLY seed", async () => {
    const { loadOrCreateKey } = require(h.r("issuer", "src", "keys.js"));
    const dir = path.join(h.tmpDir("keys"), "keys"); // not yet existing: the issuer creates it
    const k1 = loadOrCreateKey(dir);
    const k2 = loadOrCreateKey(dir);
    assert.deepEqual(k1, k2);
    const file = path.join(dir, "issuer.key");
    assert.equal(fs.statSync(file).mode & 0o777, 0o600);
    assert.equal(fs.statSync(dir).mode & 0o777, 0o700);
    fs.chmodSync(file, 0o640);
    assert.throws(() => loadOrCreateKey(dir), /permissions/);
    const testKey = h.testOnlyIssuerPrv();
    assert.notDeepEqual(k1, testKey);
    // GET /issuer exposes the public key only
    const iss = await h.makeIssuer();
    try {
      const body = (await iss.app.inject({ method: "GET", url: "/issuer" })).body;
      const prv = fs.readFileSync(path.join(iss.keyDir, "issuer.key"), "utf8").trim();
      assert.ok(!body.includes(prv));
      assert.deepEqual(Object.keys(JSON.parse(body).issuer).sort(), ["Ax", "Ay"]);
      assert.ok(!iss.sink.text().includes(prv));
    } finally {
      await iss.app.close();
    }
  });

  // F9.06 is superseded by F9.12 only once a multi-party phase 2 is committed (G2-S1-SAFETY-022):
  // while every committed key is single-party it stays a hard test; F9.12 asserts the same for that
  // case and adds the multi-party rule. Body unchanged (append-only, tests/safety/README.md).
  test("F9.06 committed proving artefacts are labelled DEV-ONLY with their limitations", { todo: F906_SUPERSEDED }, () => {
    for (const name of ["integrated_access_v3", "integrated_access_v4"]) {
      const m = h.readJson(h.r("circuits", "setup", `${name}.manifest.json`));
      assert.equal(m.status, "DEV-ONLY", name);
      assert.ok(m.limitations.some((l) => /single-party phase 2/.test(l)), name);
    }
    const fx = h.fixtureIndex();
    assert.match(fx.TEST_ONLY, /DEV-ONLY/);
  });

  test("F9.07 SR-10: the issuer key directory is created 0700 past any umask, and a group/other-accessible one is refused with no key written", async () => {
    const { loadOrCreateKey } = require(h.r("issuer", "src", "keys.js"));
    const old = process.umask(0o000);
    try {
      const dir = path.join(h.tmpDir("keys-umask"), "a", "keys"); // parents too
      loadOrCreateKey(dir);
      assert.equal(fs.statSync(dir).mode & 0o777, 0o700);
      assert.equal(fs.statSync(path.join(dir, "issuer.key")).mode & 0o777, 0o600);
    } finally {
      process.umask(old);
    }
    for (const mode of [0o755, 0o750, 0o711, 0o701, 0o770, 0o777]) {
      const dir = h.tmpDir("keys-open");
      fs.chmodSync(dir, mode);
      assert.throws(() => loadOrCreateKey(dir), /group\/other/, mode.toString(8));
      assert.deepEqual(fs.readdirSync(dir), [], `${mode.toString(8)}: a key was written into an open directory`);
    }
    // a key that already sits in a directory later opened up is refused as well (not just new ones)
    const dir = path.join(h.tmpDir("keys-later"), "keys");
    loadOrCreateKey(dir);
    fs.chmodSync(dir, 0o755);
    assert.throws(() => loadOrCreateKey(dir), /group\/other/);
    // and the whole issuer refuses to start on such a directory
    const open = h.tmpDir("keys-srv");
    fs.chmodSync(open, 0o755);
    await assert.rejects(h.makeIssuer({ overrides: { keyDir: open, logLevel: "silent" } }));
    assert.deepEqual(fs.readdirSync(open), []);
  });

  test("F9.08 SR-04: without ISSUER_ADMIN_TOKEN the issuer does not start (no key created, no state written) unless insecure-dev is exactly on", async () => {
    const { buildServer } = require(h.r("issuer", "src", "server.js"));
    const { loadConfig } = require(h.r("issuer", "src", "config.js"));
    for (const profile of ["v4", "v3"]) {
      for (const adminToken of [undefined, null, ""]) {
        for (const insecureDev of [false, undefined]) { // loadConfig (below) is the boundary that yields the boolean
          const keyDir = path.join(h.tmpDir("sr04-k"), "keys");
          const dataDir = h.tmpDir("sr04-d");
          await assert.rejects(
            buildServer({ config: { profile, keyDir, dataDir, host: "127.0.0.1", port: 0, stalenessSeconds: 30, historyRetentionSeconds: 900, logLevel: "silent", adminToken, insecureDev } }),
            /ISSUER_ADMIN_TOKEN/,
            `${profile} token=${JSON.stringify(adminToken)} insecureDev=${JSON.stringify(insecureDev)}`,
          );
          assert.ok(!fs.existsSync(path.join(keyDir, "issuer.key")), "a refused start created a key");
          assert.deepEqual(fs.readdirSync(dataDir), [], "a refused start wrote state");
        }
      }
    }
    // the environment switch is on only for the exact string "1"
    for (const v of [undefined, "", "0", "true", "yes", "1 ", "TRUE"]) {
      const env = v === undefined ? {} : { ISSUER_INSECURE_DEV: v };
      assert.equal(loadConfig(env).insecureDev, false, JSON.stringify(v));
    }
    assert.equal(loadConfig({ ISSUER_INSECURE_DEV: "1" }).insecureDev, true);
    // with a token the admin surface is closed to a missing or wrong bearer
    const iss = await h.makeIssuer({ overrides: { logLevel: "silent" } });
    try {
      for (const [m, u] of [["GET", "/admin/leaves"], ["GET", "/admin/tree"], ["GET", "/admin/enrolments"], ["POST", "/credentials/0/revoke"]]) {
        for (const tok of [null, "nope", `${iss.token}x`]) {
          const res = await iss.admin(m, u, undefined, tok);
          assert.equal(res.statusCode, 401, `${m} ${u} with ${JSON.stringify(tok)}`);
        }
      }
    } finally {
      await iss.app.close();
    }
  });

  // --- G1 gate floors review (after the PSE ppot 0080 re-key, G2-S1-CIRC-040a, and the SR-20 fix, G1-S1-IDEN-015) ---

  test("F9.09 committed keys record a public phase 1 with provenance, and stay DEV-ONLY while phase 2 is single-party", () => {
    // Forward-safe: a later multi-party phase 2 may drop the single-party limitation, but no committed
    // key may ever be built on a local (dev) or unknown (external) phase 1 again.
    const ptauSh = fs.readFileSync(h.r("circuits", "scripts", "ptau.sh"), "utf8");
    const pinBlock = /declare -A PSE_B2=\(([\s\S]*?)\n\)/.exec(ptauSh);
    assert.ok(pinBlock, "ptau.sh lost its PSE_B2 pin table");
    const pins = Object.fromEntries([...pinBlock[1].matchAll(/\[(\d+)\]=([0-9a-f]{128})/g)].map((m) => [m[1], m[2]]));
    for (const name of ["integrated_access_v3", "integrated_access_v4"]) {
      const m = h.readJson(h.r("circuits", "setup", `${name}.manifest.json`));
      assert.ok(["pse-ppot-0080", "hermez"].includes(m.ptau.source), `${name}: phase 1 source ${m.ptau.source} is not a public ceremony`);
      assert.match(m.ptau.blake2b, /^[0-9a-f]{128}$/, name);
      if (m.ptau.source === "pse-ppot-0080") {
        assert.equal(m.ptau.file, `ppot_0080_${m.ptau.power}.ptau`, name);
        assert.equal(m.ptau.blake2b, pins[String(m.ptau.power)], `${name}: manifest blake2b != ptau.sh pin`);
        // provenance names the source, the 0080 transcript linkage, and what was NOT verified
        assert.match(m.ptau.provenance, /pse-trusted-setup-ppot\.s3\.eu-central-1\.amazonaws\.com\/pot28_0080/, name);
        assert.match(m.ptau.provenance, /challenge_0080 hash \(d9ec6fad4a7a7e3358a0c4bed7171622/, name);
        assert.match(m.ptau.provenance, /challenge_0081 hash \(4bf672f3ba1de1bb6105e1ab88359612/, name);
        assert.match(m.ptau.provenance, /pinned on first download/, name);
        assert.match(m.ptau.provenance, /full snarkjs powersoftau verify not run/, name);
        assert.ok(m.limitations.some((l) => /pinned on first download/.test(l)), `${name}: TOFU pin not listed as a limitation`);
      }
      if (!(m.phase2 && m.phase2.contributions >= 2)) {
        assert.equal(m.status, "DEV-ONLY", name);
        assert.match(m.status_detail, /single-party phase 2/, name);
        assert.ok(m.limitations.some((l) => /single-party phase 2.*could forge proofs/.test(l)), name);
      }
    }
  });

  test("F9.10 committed artefacts match their manifests, and the v4 fixtures verify only under the current vkey", async (t) => {
    const crypto = require("crypto");
    const sha = (f) => crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex");
    for (const name of ["integrated_access_v3", "integrated_access_v4"]) {
      const m = h.readJson(h.r("circuits", "setup", `${name}.manifest.json`));
      assert.equal(sha(h.r("circuits", "setup", `${name}.verification_key.json`)), m.verification_key_sha256, name);
      assert.equal(sha(h.r("circuits", "setup", `${name}.zkey`)), m.zkey_sha256, name);
    }
    const m4 = h.readJson(h.r("circuits", "setup", "integrated_access_v4.manifest.json"));
    assert.equal(sha(h.V4_WASM), m4.wasm_sha256);
    const idx = h.fixtureIndex();
    assert.equal(idx.verification_key_sha256, m4.verification_key_sha256, "fixtures.json names another vkey");
    assert.equal(idx.zkey_sha256, m4.zkey_sha256, "fixtures.json names another zkey");
    assert.deepEqual(h.readJson(path.join(h.FIXTURES, "verification_key.json")), h.v4Vkey(), "fixtures carry a stale vkey copy");
    const vkey = h.v4Vkey();
    const names = Object.keys(idx.fixtures);
    assert.ok(names.length >= 10);
    // verify.js keeps worker threads; this is the only verifier user in this file, so release them here
    t.after(() => h.verifier.terminate());
    for (const n of names) {
      const fx = h.fixture(idx.fixtures[n].dir);
      assert.equal(await h.verifier.verify(vkey, fx.publicSignals, fx.proof), true, `${n} does not verify under the current vkey`);
    }
    // every earlier committed v4 vkey (a superseded key, e.g. the pre-re-key DEV phase 1) refuses
    // every current fixture: a re-key replaced the key, it did not keep an old one valid
    const cur = JSON.stringify(vkey);
    const revs = h.git("log", "--format=%H", "--", "circuits/setup/integrated_access_v4.verification_key.json").split("\n").filter(Boolean);
    const old = new Map();
    for (const rev of revs) {
      let txt;
      try {
        txt = h.git("show", `${rev}:circuits/setup/integrated_access_v4.verification_key.json`);
      } catch (_) {
        continue; // the file did not exist at that revision
      }
      const vk = JSON.parse(txt);
      if (JSON.stringify(vk) !== cur) old.set(JSON.stringify(vk), vk);
    }
    for (const vk of old.values()) {
      for (const n of names) {
        const fx = h.fixture(idx.fixtures[n].dir);
        assert.equal(await h.verifier.verify(vk, fx.publicSignals, fx.proof), false, `${n} verifies under a superseded v4 vkey`);
      }
    }
  });

  test("F9.11 SR-20: only a boolean true turns insecure-dev on in buildServer; truthy strings/numbers keep the start refused", async () => {
    const { buildServer } = require(h.r("issuer", "src", "server.js"));
    for (const profile of ["v4", "v3"]) {
      for (const insecureDev of ["0", "1", "true", "false", 1, {}, []]) {
        const keyDir = path.join(h.tmpDir("sr20-k"), "keys");
        const dataDir = h.tmpDir("sr20-d");
        await assert.rejects(
          buildServer({ config: { profile, keyDir, dataDir, host: "127.0.0.1", port: 0, stalenessSeconds: 30, historyRetentionSeconds: 900, logLevel: "silent", adminToken: undefined, insecureDev } }),
          /ISSUER_ADMIN_TOKEN/,
          `${profile} insecureDev=${JSON.stringify(insecureDev)}`,
        );
        assert.ok(!fs.existsSync(path.join(keyDir, "issuer.key")), "a refused start created a key");
        assert.deepEqual(fs.readdirSync(dataDir), [], "a refused start wrote state");
      }
    }
  });

  // --- G2-S1-SAFETY-022: ceremony-ready status rule (supersedes F9.06 once a multi-party key is committed) ---

  // F9.12 is superseded by F9.13 (ID, title and body unchanged; only the todo option added): its
  // part-3 single-party negatives mutate the committed v4 manifest, which is multi-party since the
  // 2026-11-23 ceremony, so three of them no longer violate anything. F9.13 asserts everything
  // F9.12 does, on bases that keep their kind, and adds the one-phase-2-line rule.
  test("F9.12 a key's status never outruns its provenance: single-party => DEV-ONLY, full multi-party evidence => DEMO-ONLY (never production), fixtures say the same", { todo: "superseded by F9.13: its single-party negatives mutated the v4 manifest, which is multi-party since the 2026-11-23 ceremony" }, () => {
    const crypto = require("crypto");
    const clone = (o) => JSON.parse(JSON.stringify(o));
    // 1. the committed manifests and fixtures
    for (const name of SETUP_NAMES) {
      const m = committedManifest(name);
      assert.deepEqual(provenanceViolations(m, readTreeFile), [], name);
      // a multi-party claim is backed by a transcript committed in the tree
      if (claimsMultiParty(m)) assert.equal(typeof readTreeFile(m.phase2.transcript), "string", `${name}: transcript not committed`);
    }
    const v4 = committedManifest("integrated_access_v4");
    assert.deepEqual(fixtureTextViolations(h.fixtureIndex().TEST_ONLY, v4), [], "fixtures TEST_ONLY");

    // 2. what `ceremony.sh finalize` writes (buildManifest), on synthetic inputs, passes
    const { buildManifest } = require(h.r("circuits", "scripts", "ceremony-transcript.js"));
    const H = (s) => crypto.createHash("sha512").update(s).digest("hex");
    const base = clone(v4);
    const mkT = (n, pub, source = "pse-ppot-0080") => ({
      format: "zk-access-gate.ceremony-transcript v1",
      name: "integrated_access_v4",
      ptau: { ...clone(base.ptau), source },
      contributions: Array.from({ length: n }, (_, i) => ({ order: i + 1, participant: `Person ${i + 1}`, contribution_hash: H(`c${i}`) })),
      beacon: { name: "final beacon", hash: "cd".repeat(32), iterations_exp: 10, source: "drand mainnet round R", public: pub, contribution_hash: H("beacon") },
    });
    const REL = "circuits/ceremony/integrated_access_v4/transcript.json";
    const build = (t, mBase = base) => {
      const text = JSON.stringify(t, null, 2) + "\n";
      const sha = crypto.createHash("sha256").update(text).digest("hex");
      return { m: buildManifest(clone(mBase), t, REL, sha), read: (rel) => (rel === REL ? text : null) };
    };
    const demo = build(mkT(3, true));
    assert.equal(demo.m.status, "DEMO-ONLY");
    assert.deepEqual(provenanceViolations(demo.m, demo.read), [], "3 contributors, public beacon");
    const two = build(mkT(2, true));
    assert.equal(two.m.status, "DEMO-ONLY");
    assert.deepEqual(provenanceViolations(two.m, two.read), [], "2 contributors, public beacon");
    const devBeacon = build(mkT(3, false));
    assert.equal(devBeacon.m.status, "DEV-ONLY");
    assert.deepEqual(provenanceViolations(devBeacon.m, devBeacon.read), [], "local beacon -> DEV-ONLY");
    const devP1 = build(mkT(3, true, "dev"), { ...base, ptau: { ...base.ptau, source: "dev" } });
    assert.equal(devP1.m.status, "DEV-ONLY");
    assert.deepEqual(provenanceViolations(devP1.m, devP1.read), [], "dev phase 1 -> DEV-ONLY");
    const one = build(mkT(1, true));
    assert.equal(one.m.status, "DEV-ONLY");
    assert.deepEqual(provenanceViolations(one.m, one.read), [], "1 contribution -> DEV-ONLY");
    const demoText = "TEST-ONLY fixtures. Proofs are valid under a DEMO-ONLY key (phase 1 PSE ppot 0080; multi-party phase 2, 3 contributors). Never use outside tests.";
    assert.deepEqual(fixtureTextViolations(demoText, demo.m), []);

    // 3. mismatched combinations fail
    const bad = (label, m, read = demo.read) => assert.notDeepEqual(provenanceViolations(m, read), [], `accepted: ${label}`);
    const mut = (src, f) => {
      const m = clone(src);
      f(m);
      return m;
    };
    bad("single-party committed key relabelled DEMO-ONLY", mut(v4, (m) => { m.status = "DEMO-ONLY"; }), readTreeFile);
    bad("single-party committed key without its limitation", mut(v4, (m) => { m.limitations = m.limitations.filter((l) => !/single-party/.test(l)); }), readTreeFile);
    bad("single-party committed key claiming multi-party", mut(v4, (m) => { m.limitations.push("multi-party phase 2 (1 contributors: x): could forge proofs"); }), readTreeFile);
    bad("single-party committed key inflated to 2 contributions", mut(v4, (m) => { m.phase2.contributions = 2; m.status = "DEMO-ONLY"; }), readTreeFile);
    bad("status PRODUCTION", mut(demo.m, (m) => { m.status = "PRODUCTION"; }));
    bad("status_detail without 'not for production'", mut(demo.m, (m) => { m.status_detail = "DEMO-ONLY (multi-party phase 2)"; }));
    bad("contributions as an array", mut(demo.m, (m) => { m.phase2.contributions = m.phase2.contributors; }));
    bad("contributions missing", mut(demo.m, (m) => { delete m.phase2.contributions; }));
    bad("1 contribution labelled DEMO-ONLY", mut(one.m, (m) => { m.status = "DEMO-ONLY"; }), one.read);
    bad("local beacon labelled DEMO-ONLY", mut(devBeacon.m, (m) => { m.status = "DEMO-ONLY"; }), devBeacon.read);
    bad("dev phase 1 labelled DEMO-ONLY", mut(devP1.m, (m) => { m.status = "DEMO-ONLY"; }), devP1.read);
    bad("beacon_public flipped without a public beacon in the transcript", mut(devBeacon.m, (m) => { m.status = "DEMO-ONLY"; m.phase2.beacon_public = true; }), devBeacon.read);
    bad("no transcript hash", mut(demo.m, (m) => { delete m.phase2.transcript_sha256; }));
    bad("transcript hash of another file", mut(demo.m, (m) => { m.phase2.transcript_sha256 = "0".repeat(64); }));
    bad("transcript not in the tree", demo.m, () => null);
    bad("no contributors", mut(demo.m, (m) => { delete m.phase2.contributors; }));
    bad("contributors shorter than contributions", mut(demo.m, (m) => { m.phase2.contributors.pop(); }));
    bad("contributions inflated past the transcript", mut(demo.m, (m) => { m.phase2.contributions = 4; m.phase2.contributors.push({ order: 4, participant: "Ghost", hash: H("g") }); }));
    bad("contributor renamed vs the transcript", mut(demo.m, (m) => { m.phase2.contributors[1].participant = "Mallory"; }));
    bad("contributor with an empty name", mut(demo.m, (m) => { m.phase2.contributors[0].participant = " "; }));
    bad("contributor hashes repeated", mut(demo.m, (m) => { m.phase2.contributors[1].hash = m.phase2.contributors[0].hash; }));
    bad("beacon hash differs from the transcript", mut(demo.m, (m) => { m.phase2.beacon_hash = "ab".repeat(32); }));
    bad("no beacon contribution hash", mut(demo.m, (m) => { delete m.phase2.beacon_contribution_hash; }));
    bad("phase 1 differs from the transcript", mut(demo.m, (m) => { m.ptau.blake2b = "0".repeat(128); }));
    bad("multi-party key labelled DEV-ONLY (status follows the evidence)", mut(demo.m, (m) => { m.status = "DEV-ONLY"; }));
    bad("multi-party key without the multi-party limitation", mut(demo.m, (m) => { m.limitations = m.limitations.filter((l) => !/multi-party/.test(l)); }));
    bad("multi-party key still listing the single-party limitation", mut(demo.m, (m) => { m.limitations.push(v4.limitations[0]); }));
    bad("local beacon DEV-ONLY without the beacon limitation", mut(devBeacon.m, (m) => { m.limitations = m.limitations.filter((l) => !/beacon is local/.test(l)); }), devBeacon.read);
    const fxBad = (label, text, m) => assert.notDeepEqual(fixtureTextViolations(text, m), [], `accepted fixtures text: ${label}`);
    fxBad("current single-party text under a DEMO-ONLY key", h.fixtureIndex().TEST_ONLY, demo.m);
    fxBad("DEMO-ONLY text without multi-party", "TEST-ONLY fixtures, DEMO-ONLY key. Never use outside tests.", demo.m);
    fxBad("multi-party text under the single-party key", demoText, v4);
    fxBad("single-party text that also claims multi-party", `${h.fixtureIndex().TEST_ONLY} Now a multi-party phase 2.`, v4);
    fxBad("no TEST-ONLY marker", demoText.replace("TEST-ONLY", "fixtures"), demo.m);
    fxBad("single-party key text without the limitation", "TEST-ONLY fixtures under a DEV-ONLY key. Never use outside tests.", v4);
    fxBad("no use restriction", demoText.replace(" Never use outside tests.", ""), demo.m);
  });

  // --- F9.13: supersedes F9.12 (multi-party v4 since the 2026-11-23 ceremony) ---
  // Same rule as F9.12, but every negative is built from a base that keeps its kind whatever is
  // committed: single-party negatives from a committed single-party manifest (v3 today) AND from a
  // synthetic single-party build; multi-party negatives from every committed multi-party manifest
  // (v4 today) AND from a synthetic multi-party build. Tightened: exactly one phase-2 limitation
  // line, consistent with phase2.contributions / contributors / limitation (phase2LineViolations).

  test("F9.13 a key's status never outruns its provenance, on single- and multi-party bases alike; exactly one phase-2 limitation line, consistent with its contributors", () => {
    const crypto = require("crypto");
    const clone = (o) => JSON.parse(JSON.stringify(o));
    const mut = (src, f) => {
      const m = clone(src);
      f(m);
      return m;
    };
    // 1. the committed manifests and fixtures
    const committed = SETUP_NAMES.map((name) => ({ name, m: committedManifest(name) }));
    for (const { name, m } of committed) {
      assert.deepEqual(strictViolations(m, readTreeFile), [], name);
      if (claimsMultiParty(m)) assert.equal(typeof readTreeFile(m.phase2.transcript), "string", `${name}: transcript not in the tree`);
    }
    const v4 = committedManifest("integrated_access_v4");
    assert.deepEqual(fixtureTextViolations(h.fixtureIndex().TEST_ONLY, v4), [], "fixtures TEST_ONLY vs the v4 key");

    // 2. what `ceremony.sh finalize` writes (buildManifest), on synthetic transcripts, from a
    //    single-party base and from a multi-party base (idempotent: no stale phase-2 line survives)
    const { buildManifest } = require(h.r("circuits", "scripts", "ceremony-transcript.js"));
    const H = (s) => crypto.createHash("sha512").update(s).digest("hex");
    const singleCommitted = committed.filter((c) => !claimsMultiParty(c.m));
    const multiCommitted = committed.filter((c) => claimsMultiParty(c.m));
    assert.ok(singleCommitted.length + multiCommitted.length === SETUP_NAMES.length);
    const REL = "circuits/ceremony/integrated_access_v4/transcript.json";
    const mkT = (base, n, pub, source = "pse-ppot-0080", tag = "") => ({
      format: "zk-access-gate.ceremony-transcript v1",
      name: "integrated_access_v4",
      ptau: { ...clone(base.ptau), source },
      contributions: Array.from({ length: n }, (_, i) => ({ order: i + 1, participant: `Person ${i + 1}${tag}`, contribution_hash: H(`c${i}${tag}`) })),
      beacon: { name: "final beacon", hash: "cd".repeat(32), iterations_exp: 10, source: "drand mainnet round R", public: pub, contribution_hash: H(`beacon${tag}`) },
    });
    const build = (base, t, patchBase) => {
      const text = JSON.stringify(t, null, 2) + "\n";
      const sha = crypto.createHash("sha256").update(text).digest("hex");
      const b = clone(base);
      if (patchBase) patchBase(b);
      return { m: buildManifest(b, t, REL, sha), read: (rel) => (rel === REL ? text : null) };
    };
    const ok = (label, x) => assert.deepEqual(strictViolations(x.m, x.read), [], label);
    const bases = [...committed.map((c) => ({ label: `committed ${c.name}`, m: c.m }))];
    const builds = {};
    for (const { label, m } of bases) {
      const demo = build(m, mkT(m, 3, true));
      assert.equal(demo.m.status, "DEMO-ONLY", label);
      ok(`${label}: 3 contributors, public beacon`, demo);
      const two = build(m, mkT(m, 2, true));
      assert.equal(two.m.status, "DEMO-ONLY", label);
      ok(`${label}: 2 contributors`, two);
      const devBeacon = build(m, mkT(m, 3, false));
      assert.equal(devBeacon.m.status, "DEV-ONLY", label);
      ok(`${label}: local beacon -> DEV-ONLY`, devBeacon);
      const devP1 = build(m, mkT(m, 3, true, "dev"), (b) => { b.ptau = { ...b.ptau, source: "dev" }; });
      assert.equal(devP1.m.status, "DEV-ONLY", label);
      ok(`${label}: dev phase 1 -> DEV-ONLY`, devP1);
      const one = build(m, mkT(m, 1, true));
      assert.equal(one.m.status, "DEV-ONLY", label);
      ok(`${label}: 1 contribution -> DEV-ONLY`, one);
      // re-finalising on top of a multi-party result (2 -> 3 people, then 3 -> 1) leaves one line
      const again = build(demo.m, mkT(m, 2, true, "pse-ppot-0080", "b"));
      ok(`${label}: rebuilt 3 -> 2 contributors`, again);
      const back = build(demo.m, mkT(m, 1, true, "pse-ppot-0080", "c"));
      assert.equal(back.m.status, "DEV-ONLY");
      ok(`${label}: rebuilt 3 -> 1 contribution`, back);
      builds[label] = { demo, two, devBeacon, devP1, one };
    }
    const S = builds[bases[0].label];
    const demoText = "TEST-ONLY fixtures. Proofs are valid under a DEMO-ONLY key (phase 1 PSE ppot 0080; multi-party phase 2, 3 contributors). Never use outside tests.";
    const singleText = "TEST-ONLY fixtures. Proofs are valid under a DEV-ONLY key (phase 1 PSE ppot 0080; single-party phase 2, so whoever ran setup could forge proofs). Never use outside tests.";
    assert.deepEqual(fixtureTextViolations(demoText, S.demo.m), []);
    assert.deepEqual(fixtureTextViolations(singleText, S.one.m), []);

    // 3. mismatched combinations fail
    const bad = (label, m, read) => assert.notDeepEqual(strictViolations(m, read), [], `accepted: ${label}`);
    // 3a. single-party negatives: committed single-party keys (stay single-party) + synthetic one
    const singles = [
      ...singleCommitted.map((c) => ({ label: `committed ${c.name}`, m: c.m, read: readTreeFile })),
      ...Object.entries(builds).map(([l, b]) => ({ label: `synthetic 1-contribution (${l})`, m: b.one.m, read: b.one.read })),
    ];
    assert.ok(singles.length >= 2);
    for (const { label, m, read } of singles) {
      assert.ok(!claimsMultiParty(m), `${label} must be single-party`);
      bad(`${label} relabelled DEMO-ONLY`, mut(m, (x) => { x.status = "DEMO-ONLY"; }), read);
      bad(`${label} without its single-party limitation`, mut(m, (x) => { x.limitations = x.limitations.filter((l) => !/single-party/.test(l)); }), read);
      bad(`${label} also claiming multi-party`, mut(m, (x) => { x.limitations.push("multi-party phase 2 (1 contributors: x): could forge proofs"); }), read);
      bad(`${label} with its line replaced by a multi-party one`, mut(m, (x) => { x.limitations = x.limitations.map((l) => (/single-party/.test(l) ? "multi-party phase 2 (1 contributors: x): could forge proofs" : l)); }), read);
      bad(`${label} inflated to 2 contributions`, mut(m, (x) => { x.phase2.contributions = 2; x.status = "DEMO-ONLY"; }), read);
      bad(`${label} with 2 contributions and DEV-ONLY (line still single-party)`, mut(m, (x) => { x.phase2.contributions = 2; }), read);
      bad(`${label} with the single-party line twice`, mut(m, (x) => { x.limitations.push(x.limitations.find((l) => /single-party/.test(l))); }), read);
      bad(`${label} status_detail claiming multi-party`, mut(m, (x) => { x.status = "DEMO-ONLY"; x.status_detail = "DEMO-ONLY (multi-party phase 2): not for production"; }), read);
    }
    // 3b. multi-party negatives: committed multi-party keys + every synthetic multi-party build
    const multis = [
      ...multiCommitted.map((c) => ({ label: `committed ${c.name}`, m: c.m, read: readTreeFile })),
      ...Object.entries(builds).flatMap(([l, b]) => [
        { label: `synthetic 3 (${l})`, m: b.demo.m, read: b.demo.read },
        { label: `synthetic 2 (${l})`, m: b.two.m, read: b.two.read },
      ]),
    ];
    for (const { label, m, read } of multis) {
      const n = m.phase2.contributions;
      assert.ok(claimsMultiParty(m) && m.status === "DEMO-ONLY", `${label} must be a DEMO-ONLY multi-party key`);
      bad(`${label} with an extra 1-contributor line`, mut(m, (x) => { x.limitations.push("multi-party phase 2 (1 contributors: x): could forge proofs"); }), read);
      bad(`${label} with its line duplicated`, mut(m, (x) => { x.limitations.push(x.limitations.find((l) => /multi-party/.test(l))); }), read);
      bad(`${label} with contributions set to 1`, mut(m, (x) => { x.phase2.contributions = 1; }), read);
      bad(`${label} with contributions set to 1 and DEV-ONLY`, mut(m, (x) => { x.phase2.contributions = 1; x.status = "DEV-ONLY"; }), read);
      bad(`${label} with contributions != contributors`, mut(m, (x) => { x.phase2.contributions = n + 1; }), read);
      bad(`${label} with a line naming another count`, mut(m, (x) => { x.limitations = x.limitations.map((l) => l.replace(/multi-party phase 2 \(\d+/, `multi-party phase 2 (${n + 1}`)); }), read);
      bad(`${label} with a line naming other people`, mut(m, (x) => { x.limitations = x.limitations.map((l) => l.replace(/contributors: [^,)]*/, "contributors: Mallory")); }), read);
      bad(`${label} with phase2.limitation contradicting the list`, mut(m, (x) => { x.phase2.limitation = "multi-party phase 2 (1 contributors: x): could forge proofs"; }), read);
      bad(`${label} relabelled DEV-ONLY`, mut(m, (x) => { x.status = "DEV-ONLY"; }), read);
      bad(`${label} relabelled PRODUCTION`, mut(m, (x) => { x.status = "PRODUCTION"; }), read);
      bad(`${label} without the multi-party limitation`, mut(m, (x) => { x.limitations = x.limitations.filter((l) => !/multi-party/.test(l)); }), read);
      bad(`${label} also listing the single-party limitation`, mut(m, (x) => { x.limitations.push(singles[0].m.limitations.find((l) => /single-party/.test(l))); }), read);
      bad(`${label} status_detail without 'not for production'`, mut(m, (x) => { x.status_detail = "DEMO-ONLY (multi-party phase 2)"; }), read);
      bad(`${label} contributions as an array`, mut(m, (x) => { x.phase2.contributions = x.phase2.contributors; }), read);
      bad(`${label} contributions missing`, mut(m, (x) => { delete x.phase2.contributions; }), read);
      bad(`${label} no transcript hash`, mut(m, (x) => { delete x.phase2.transcript_sha256; }), read);
      bad(`${label} transcript hash of another file`, mut(m, (x) => { x.phase2.transcript_sha256 = "0".repeat(64); }), read);
      bad(`${label} transcript not in the tree`, m, () => null);
      bad(`${label} no contributors`, mut(m, (x) => { delete x.phase2.contributors; }), read);
      bad(`${label} contributors shorter than contributions`, mut(m, (x) => { x.phase2.contributors.pop(); }), read);
      bad(`${label} contributions inflated past the transcript`, mut(m, (x) => { x.phase2.contributions = n + 1; x.phase2.contributors.push({ order: n + 1, participant: "Ghost", hash: H("g") }); }), read);
      bad(`${label} contributor renamed vs the transcript`, mut(m, (x) => { x.phase2.contributors[1].participant = "Mallory"; }), read);
      bad(`${label} contributor with an empty name`, mut(m, (x) => { x.phase2.contributors[0].participant = " "; }), read);
      bad(`${label} contributor hashes repeated`, mut(m, (x) => { x.phase2.contributors[1].hash = x.phase2.contributors[0].hash; }), read);
      bad(`${label} beacon hash differs from the transcript`, mut(m, (x) => { x.phase2.beacon_hash = "ab".repeat(32); }), read);
      bad(`${label} beacon not public`, mut(m, (x) => { x.phase2.beacon_public = false; }), read);
      bad(`${label} no beacon contribution hash`, mut(m, (x) => { delete x.phase2.beacon_contribution_hash; }), read);
      bad(`${label} phase 1 differs from the transcript`, mut(m, (x) => { x.ptau.blake2b = "0".repeat(128); }), read);
      bad(`${label} phase 1 not public`, mut(m, (x) => { x.ptau.source = "dev"; }), read);
    }
    // 3c. DEV-ONLY multi-contribution keys (local beacon / dev phase 1)
    for (const [l, b] of Object.entries(builds)) {
      bad(`local beacon labelled DEMO-ONLY (${l})`, mut(b.devBeacon.m, (x) => { x.status = "DEMO-ONLY"; }), b.devBeacon.read);
      bad(`dev phase 1 labelled DEMO-ONLY (${l})`, mut(b.devP1.m, (x) => { x.status = "DEMO-ONLY"; }), b.devP1.read);
      bad(`beacon_public flipped without a public beacon in the transcript (${l})`, mut(b.devBeacon.m, (x) => { x.status = "DEMO-ONLY"; x.phase2.beacon_public = true; }), b.devBeacon.read);
      bad(`local beacon DEV-ONLY without the beacon limitation (${l})`, mut(b.devBeacon.m, (x) => { x.limitations = x.limitations.filter((y) => !/beacon is local/.test(y)); }), b.devBeacon.read);
      bad(`local beacon DEV-ONLY with an extra 1-contributor line (${l})`, mut(b.devBeacon.m, (x) => { x.limitations.push("multi-party phase 2 (1 contributors: x): could forge proofs"); }), b.devBeacon.read);
    }
    // 3d. the fixtures' TEST_ONLY text must match the kind of key it is proved under
    const fxBad = (label, text, m) => assert.notDeepEqual(fixtureTextViolations(text, m), [], `accepted fixtures text: ${label}`);
    const multiKey = multiCommitted.length ? multiCommitted[0].m : S.demo.m;
    const singleKey = singleCommitted.length ? singleCommitted[0].m : S.one.m;
    fxBad("single-party text under a multi-party key", singleText, multiKey);
    fxBad("multi-party text under a single-party key", demoText, singleKey);
    fxBad("the committed fixtures text under the other kind of key", h.fixtureIndex().TEST_ONLY, claimsMultiParty(v4) ? singleKey : multiKey);
    fxBad("DEMO-ONLY text without multi-party", "TEST-ONLY fixtures, DEMO-ONLY key. Never use outside tests.", multiKey);
    fxBad("multi-party text that also says single-party", `${demoText} Formerly single-party.`, multiKey);
    fxBad("single-party text that also claims multi-party", `${singleText} Now a multi-party phase 2.`, singleKey);
    fxBad("single-party key text without the limitation", "TEST-ONLY fixtures under a DEV-ONLY key. Never use outside tests.", singleKey);
    fxBad("no TEST-ONLY marker", demoText.replace("TEST-ONLY", "fixtures"), multiKey);
    fxBad("no use restriction", demoText.replace(" Never use outside tests.", ""), multiKey);
  });
});
